INSERT INTO homepage_content (module, content) VALUES
('about', '{"subText":"实验室介绍","headText":"关于0436.","description":"0436 系统设计实验室专注前后端开发、智能计算与 AI 创新，为计算机专业学生提供系统化分层编程培训，拥有完善的前端、后端完整学习路线；实验室成员学业成绩优异，在挑战杯、计算机设计大赛、蓝桥杯等国家级赛事斩获多项一二三等奖；团队自主研发 Queue 学习平台、LeSoun AI 音乐创作等实战项目，还有多学科合作研发任务；实验室硬件配置顶配，配有独立服务器、双屏工位、打印机、冰箱与双中央空调，环境舒适；日常会组织聚餐、剧本杀等团建活动，学习氛围轻松互助，零基础同学也能得到学长学姐全程带教，欢迎热爱编程、竞赛、开发的同学加入 QQ 群了解纳新详情。","services":[{"title":"在线判题","icon":""},{"title":"编程赛事","icon":""},{"title":"技术社区","icon":""},{"title":"AI 助手","icon":""}]}'::jsonb),
('experiences', '{"subText":"核心优势","headText":"实验室功能.","items":[{"title":"竞赛升学优势","company_name":"Advantages in Competition & Further Study","icon":"","iconBg":"#ffffff","points":["学业升学成果突出，实验室往届学长学姐连续两年拿下计算机学院专业第一名，多名成员成功上岸985、211重点院校，为学弟学妹提供成熟升学指导路径。","国家级赛事奖项丰厚，团队先后斩获挑战杯一等奖、中国大学生计算机设计大赛国三、蓝桥杯省赛一二三等奖及全国总决赛奖项，覆盖 Java、C/C++ 多赛道，赛事成果可直接用于综测加分、奖学金评定、考研复试与校招简历背书。"]},{"title":"培训实战优势","company_name":"Advantages of Training & Practical Development","icon":"","iconBg":"#ffffff","points":["拥有前后端完整分层教学体系，学长学姐一对一全程带教，零基础可循序渐进上手主流开发技术。","坐拥多款全栈、AI 落地自研项目，可查看完整源码，积累能够直接写入简历的开发实战经历。"]},{"title":"硬件环境优势","company_name":"Advantages of Hardware & Study Environment","icon":"","iconBg":"#ffffff","points":["配备独立服务器、双屏工位、人体工学椅，搭配打印机、冰箱、中央空调，学习生活配套齐全。","实验室全天开放，空间宽敞整洁，随时可进入开展编程学习与项目研发。"]},{"title":"团队氛围优势","company_name":"Advantages of Team Atmosphere","icon":"","iconBg":"#ffffff","points":["定期组织聚餐、桌游、剧本杀等团建活动，平衡学习与休闲，舒缓日常学习压力。","团队互助氛围浓厚，学长无偿分享竞赛、考研、求职经验，大家互帮互助共同进步。"]}]}'::jsonb),
('technologies', '[{"name":"HTML 5","icon":""},{"name":"CSS 3","icon":""},{"name":"JavaScript","icon":""},{"name":"TypeScript","icon":""},{"name":"React JS","icon":""},{"name":"Redux Toolkit","icon":""},{"name":"Tailwind CSS","icon":""},{"name":"Node JS","icon":""},{"name":"MongoDB","icon":""},{"name":"Three JS","icon":""},{"name":"git","icon":""},{"name":"figma","icon":""},{"name":"docker","icon":""},{"name":"Java","icon":""},{"name":"Spring","icon":""},{"name":"Spring Boot","icon":""},{"name":"Python","icon":""},{"name":"MySQL","icon":""},{"name":"Redis","icon":""},{"name":"PostgreSQL","icon":""},{"name":"Kubernetes","icon":""},{"name":"Linux","icon":""}]'::jsonb),
('works', '{"subText":"实验室荣誉","headText":"竞赛奖项.","description":"实验室鼓励成员积极参与各类学科竞赛，依托完善的技术指导体系，组织团队参与挑战杯、蓝桥杯、中国大学生计算机设计大赛等高水平学科赛事。历年参赛队伍多次斩获国家级、省级竞赛奖项，竞赛成果可用于综测加分、奖学金评定、考研复试与求职简历背书。众多成员以竞赛为契机夯实专业能力，拓展项目经验，实现综合能力持续提升。","items":[{"name":"蓝桥杯大赛","description":"组织实验室成员组队参与蓝桥杯竞赛，覆盖 Java、C/C++ 主流赛道，依托常态化刷题训练与赛前集中辅导，多名成员斩获省级一、二、三等奖及全国总决赛奖项，夯实算法编程核心能力。","image":"","tags":[{"name":"算法竞赛","color":"blue-text-gradient"},{"name":"C++","color":"green-text-gradient"},{"name":"Java","color":"pink-text-gradient"}],"source_code_link":"https://github.com/"},{"name":"中国大学生计算机设计大赛","description":"围绕软件开发、人工智能、大数据等赛道组建参赛队伍，从选题、开发到作品打磨全程指导，往届团队斩获国家级、省级奖项，锻炼完整项目开发与作品答辩能力。","image":"","tags":[{"name":"全栈开发","color":"blue-text-gradient"},{"name":"AI 项目","color":"green-text-gradient"},{"name":"作品答辩","color":"pink-text-gradient"}],"source_code_link":"https://github.com/"},{"name":"挑战杯科创竞赛","description":"聚焦科创创新课题，支持跨方向组队开展项目研发，配备学长全程指导项目撰写与路演准备，团队多次获得各级赛事荣誉，培养创新思维与团队协作能力。","image":"","tags":[{"name":"科创项目","color":"blue-text-gradient"},{"name":"创新实践","color":"green-text-gradient"},{"name":"路演备赛","color":"pink-text-gradient"}],"source_code_link":"https://github.com/"}]}'::jsonb),
('feedbacks', '{"subText":"社区声音","headText":"学长学姐寄语.","items":[{"testimonial":"愿大家在实验室保持热爱，深耕算法、坚持思考，在一次次训练与竞赛中突破自我，奔赴心中目标。","name":"往届学姐","designation":"算法竞赛方向","company":"Open436","image":"https://randomuser.me/api/portraits/women/4.jpg"},{"testimonial":"珍惜并肩学习的时光，大胆提问、动手实践。在这里沉淀的技术与友谊，终将成为前行路上珍贵的财富。","name":"往届学长","designation":"后端开发方向","company":"Open436","image":"https://randomuser.me/api/portraits/men/5.jpg"},{"testimonial":"沉下心打磨项目，积极参与科创竞赛。希望各位脚踏实地，学有所成，在考研与求职赛道收获满意答卷。","name":"往届学长","designation":"全栈开发方向","company":"Open436","image":"https://randomuser.me/api/portraits/women/6.jpg"}]}'::jsonb)
